//! The slice of the EVDI and DRM userspace ABI this backend uses.
//!
//! Every constant, struct layout and request number here is hand-copied from
//! `module/evdi_drm.h` (DisplayLink/evdi) and the kernel's `drm/drm.h`. They are checked
//! against the output of a C compiler run over the real headers by the unit test
//! `abi_matches_c_probe_fixture` (fixture:
//! `crates/display/tests/fixtures/evdi-ee3a4b2-abi.txt`, generated by
//! `scripts/evdi-abi/regen.sh`).
//!
//! What that does and does not prove: the Rust layouts equal what GCC computes for x86_64
//! LP64 from the pinned upstream headers. It does not prove the installed `evdi` module on
//! a given machine speaks the same ABI (the ioctl numbers and structs have been stable for
//! years and libevdi requires module `1.x` with `x >= 9`, which [`MIN_MODULE_MINOR`]
//! mirrors, but nothing here was run against a loaded module).
//!
//! All structs contain explicit `_pad` fields instead of implicit padding so they can be
//! viewed as bytes without exposing uninitialised memory.

use std::ffi::{c_char, c_void};
use std::mem::size_of;

// The struct layouts below (`usize` lengths, 8-byte pointers, the explicit `_pad` fields) are
// the LP64 layouts verified against a C compiler. A 32-bit build would silently produce
// wrong sizes and therefore wrong ioctl request numbers, so refuse to compile instead.
#[cfg(not(target_pointer_width = "64"))]
compile_error!(
    "the EVDI backend ABI is only verified for 64-bit (LP64) targets; the struct layouts and \
     ioctl request numbers in kernel_drm::abi would be wrong on this target"
);

// ---------------------------------------------------------------------------------------
// ioctl request encoding (asm-generic/ioctl.h, as used on x86, arm, arm64, riscv, ...)
// ---------------------------------------------------------------------------------------

pub const IOC_NONE: u32 = 0;
pub const IOC_WRITE: u32 = 1;
pub const IOC_READ: u32 = 2;

const IOC_NRSHIFT: u32 = 0;
const IOC_TYPESHIFT: u32 = 8;
const IOC_SIZESHIFT: u32 = 16;
const IOC_DIRSHIFT: u32 = 30;

/// `_IOC(dir, type, nr, size)`.
pub const fn ioc(dir: u32, ty: u8, nr: u32, size: usize) -> u32 {
    (dir << IOC_DIRSHIFT) | ((size as u32) << IOC_SIZESHIFT) | ((ty as u32) << IOC_TYPESHIFT) | nr
}

/// `_IOWR(type, nr, size)`: the driver both reads and writes the argument.
pub const fn iowr(ty: u8, nr: u32, size: usize) -> u32 {
    ioc(IOC_READ | IOC_WRITE, ty, nr, size)
}

/// Direction bits of a request.
pub const fn ioc_dir(request: u32) -> u32 {
    request >> IOC_DIRSHIFT
}

/// Argument size encoded in a request.
pub const fn ioc_size(request: u32) -> usize {
    ((request >> IOC_SIZESHIFT) & 0x3fff) as usize
}

/// Ioctl type byte of a request.
pub const fn ioc_type(request: u32) -> u8 {
    ((request >> IOC_TYPESHIFT) & 0xff) as u8
}

/// Command number of a request.
pub const fn ioc_nr(request: u32) -> u32 {
    (request >> IOC_NRSHIFT) & 0xff
}

// ---------------------------------------------------------------------------------------
// DRM core
// ---------------------------------------------------------------------------------------

/// `DRM_IOCTL_BASE`, the ioctl type byte of every DRM ioctl.
pub const DRM_IOCTL_BASE: u8 = b'd';
/// First driver-private command number.
pub const DRM_COMMAND_BASE: u32 = 0x40;

/// `struct drm_event`: header of everything `read(2)` returns from a DRM fd.
#[repr(C)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct DrmEvent {
    pub type_: u32,
    pub length: u32,
}

/// `struct drm_clip_rect`.
#[repr(C)]
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub struct DrmClipRect {
    pub x1: u16,
    pub y1: u16,
    pub x2: u16,
    pub y2: u16,
}

/// `struct drm_version` (for `DRM_IOCTL_VERSION`).
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct DrmVersion {
    pub version_major: i32,
    pub version_minor: i32,
    pub version_patchlevel: i32,
    pub _pad: u32,
    pub name_len: usize,
    pub name: *mut c_char,
    pub date_len: usize,
    pub date: *mut c_char,
    pub desc_len: usize,
    pub desc: *mut c_char,
}

/// `DRM_IOCTL_VERSION` = `DRM_IOWR(0x00, struct drm_version)`.
pub const DRM_IOCTL_VERSION: u32 = iowr(DRM_IOCTL_BASE, 0x00, size_of::<DrmVersion>());
/// `DRM_IOCTL_DROP_MASTER` = `DRM_IO(0x1f)`.
pub const DRM_IOCTL_DROP_MASTER: u32 = ioc(IOC_NONE, DRM_IOCTL_BASE, 0x1f, 0);
/// `DRM_IOCTL_AUTH_MAGIC` = `DRM_IOW(0x11, struct drm_auth)`; `struct drm_auth` is one
/// `unsigned int`. libevdi (`drm_is_master`) uses `AUTH_MAGIC` with magic 0 as a master probe:
/// it needs master, so a non-master fd fails with `EACCES` and a master fd with `EINVAL`.
pub const DRM_IOCTL_AUTH_MAGIC: u32 = ioc(IOC_WRITE, DRM_IOCTL_BASE, 0x11, 4);

// ---------------------------------------------------------------------------------------
// EVDI
// ---------------------------------------------------------------------------------------

/// DRM driver name reported by `DRM_IOCTL_VERSION` for EVDI cards.
pub const EVDI_DRIVER_NAME: &str = "evdi";
/// Module major version libevdi accepts (`EVDI_MODULE_COMPATIBILITY_VERSION_MAJOR`).
pub const MODULE_MAJOR: i32 = 1;
/// Minimum module minor version libevdi accepts (`EVDI_MODULE_COMPATIBILITY_VERSION_MINOR`).
pub const MIN_MODULE_MINOR: i32 = 9;

/// Driver command indices (relative to [`DRM_COMMAND_BASE`]).
pub const DRM_EVDI_CONNECT: u32 = 0x00;
pub const DRM_EVDI_REQUEST_UPDATE: u32 = 0x01;
pub const DRM_EVDI_GRABPIX: u32 = 0x02;

/// `struct drm_evdi_connect`.
///
/// Field order is `connected, dev_index, edid pointer, edid_length, limits`. The pointer is
/// 8-byte aligned, so `edid` sits at offset 8 and the struct is padded to 32 bytes.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct DrmEvdiConnect {
    pub connected: i32,
    pub dev_index: i32,
    pub edid: *const u8,
    pub edid_length: u32,
    pub pixel_area_limit: u32,
    pub pixel_per_second_limit: u32,
    pub _pad: u32,
}

/// `struct drm_evdi_request_update`.
#[repr(C)]
#[derive(Debug, Clone, Copy, Default)]
pub struct DrmEvdiRequestUpdate {
    pub reserved: i32,
}

/// `enum drm_evdi_grabpix_mode`. Only [`GRABPIX_MODE_DIRTY`] is accepted by the module.
pub const GRABPIX_MODE_RECTS: i32 = 0;
pub const GRABPIX_MODE_DIRTY: i32 = 1;

/// `struct drm_evdi_grabpix`.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct DrmEvdiGrabpix {
    pub mode: i32,
    pub buf_width: i32,
    pub buf_height: i32,
    pub buf_byte_stride: i32,
    pub buffer: *mut u8,
    pub num_rects: i32,
    pub _pad: u32,
    pub rects: *mut DrmClipRect,
}

/// `DRM_IOCTL_EVDI_CONNECT` = `DRM_IOWR(DRM_COMMAND_BASE + DRM_EVDI_CONNECT, struct drm_evdi_connect)`.
pub const DRM_IOCTL_EVDI_CONNECT: u32 = iowr(
    DRM_IOCTL_BASE,
    DRM_COMMAND_BASE + DRM_EVDI_CONNECT,
    size_of::<DrmEvdiConnect>(),
);
/// `DRM_IOCTL_EVDI_REQUEST_UPDATE`.
pub const DRM_IOCTL_EVDI_REQUEST_UPDATE: u32 = iowr(
    DRM_IOCTL_BASE,
    DRM_COMMAND_BASE + DRM_EVDI_REQUEST_UPDATE,
    size_of::<DrmEvdiRequestUpdate>(),
);
/// `DRM_IOCTL_EVDI_GRABPIX`.
pub const DRM_IOCTL_EVDI_GRABPIX: u32 = iowr(
    DRM_IOCTL_BASE,
    DRM_COMMAND_BASE + DRM_EVDI_GRABPIX,
    size_of::<DrmEvdiGrabpix>(),
);

/// Event types delivered by `read(2)` on the card fd.
pub const DRM_EVDI_EVENT_UPDATE_READY: u32 = 0x8000_0000;
pub const DRM_EVDI_EVENT_DPMS: u32 = 0x8000_0001;
pub const DRM_EVDI_EVENT_MODE_CHANGED: u32 = 0x8000_0002;
pub const DRM_EVDI_EVENT_CRTC_STATE: u32 = 0x8000_0003;
pub const DRM_EVDI_EVENT_CURSOR_SET: u32 = 0x8000_0004;
pub const DRM_EVDI_EVENT_CURSOR_MOVE: u32 = 0x8000_0005;
pub const DRM_EVDI_EVENT_DDCCI_DATA: u32 = 0x8000_0006;

/// Wire sizes of the events we decode (header included).
pub const EVENT_UPDATE_READY_SIZE: usize = 8;
pub const EVENT_DPMS_SIZE: usize = 12;
pub const EVENT_MODE_CHANGED_SIZE: usize = 28;
pub const EVENT_CRTC_STATE_SIZE: usize = 12;

/// An EVDI event, as far as this backend cares.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EvdiEvent {
    /// Dirty pixels are ready: `DRM_IOCTL_EVDI_GRABPIX` will return them.
    UpdateReady,
    /// Display power state changed.
    Dpms(i32),
    /// The compositor set a new mode on the CRTC.
    ModeChanged {
        hdisplay: i32,
        vdisplay: i32,
        vrefresh: i32,
        bits_per_pixel: i32,
        pixel_format: u32,
    },
    /// CRTC state (defined by the header).
    CrtcState(i32),
    /// Cursor and DDC/CI events, or anything newer, skipped by length.
    Other(u32),
}

fn u32_at(buf: &[u8], off: usize) -> u32 {
    u32::from_ne_bytes([buf[off], buf[off + 1], buf[off + 2], buf[off + 3]])
}

fn i32_at(buf: &[u8], off: usize) -> i32 {
    u32_at(buf, off) as i32
}

/// Decodes the events in a buffer returned by `read(2)`.
///
/// Mirrors `evdi_handle_events`: events are packed back to back and each one's
/// `drm_event.length` gives the stride. Decoding stops at a truncated or malformed header
/// (length smaller than the header or running past the buffer) instead of panicking.
/// Unknown types are returned as [`EvdiEvent::Other`] and skipped by length.
pub fn parse_events(buf: &[u8]) -> Vec<EvdiEvent> {
    let mut events = Vec::new();
    let mut i = 0usize;
    while i + size_of::<DrmEvent>() <= buf.len() {
        let ty = u32_at(buf, i);
        let len = u32_at(buf, i + 4) as usize;
        if len < size_of::<DrmEvent>() || i + len > buf.len() {
            break;
        }
        let ev = &buf[i..i + len];
        let event = match ty {
            DRM_EVDI_EVENT_UPDATE_READY => EvdiEvent::UpdateReady,
            DRM_EVDI_EVENT_DPMS if len >= EVENT_DPMS_SIZE => EvdiEvent::Dpms(i32_at(ev, 8)),
            DRM_EVDI_EVENT_MODE_CHANGED if len >= EVENT_MODE_CHANGED_SIZE => {
                EvdiEvent::ModeChanged {
                    hdisplay: i32_at(ev, 8),
                    vdisplay: i32_at(ev, 12),
                    vrefresh: i32_at(ev, 16),
                    bits_per_pixel: i32_at(ev, 20),
                    pixel_format: u32_at(ev, 24),
                }
            }
            DRM_EVDI_EVENT_CRTC_STATE if len >= EVENT_CRTC_STATE_SIZE => {
                EvdiEvent::CrtcState(i32_at(ev, 8))
            }
            other => EvdiEvent::Other(other),
        };
        events.push(event);
        i += len;
    }
    events
}

/// Views a plain `#[repr(C)]` struct as bytes for an ioctl.
///
/// # Safety
/// `T` must contain no implicit padding (all structs in this module spell it out with
/// `_pad` fields) so every byte is initialised, and the caller must not write through the
/// slice anything that is not a valid `T`.
pub unsafe fn as_bytes_mut<T>(value: &mut T) -> &mut [u8] {
    // SAFETY: upheld by the caller; the slice covers exactly `*value`.
    unsafe { std::slice::from_raw_parts_mut((value as *mut T).cast::<u8>(), size_of::<T>()) }
}

/// Reads a `T` back out of ioctl argument bytes.
///
/// # Safety
/// `bytes` must hold at least `size_of::<T>()` bytes forming a valid `T`.
pub unsafe fn read_struct<T: Copy>(bytes: &[u8]) -> T {
    assert!(bytes.len() >= size_of::<T>());
    // SAFETY: length checked above; `read_unaligned` tolerates any alignment.
    unsafe { std::ptr::read_unaligned(bytes.as_ptr().cast::<T>()) }
}

/// Opaque pointer type used where C has `void *`.
pub type RawPtr = *mut c_void;

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::HashMap;
    use std::mem::offset_of;

    const FIXTURE: &str = include_str!("../../../tests/fixtures/evdi-ee3a4b2-abi.txt");

    fn fixture() -> HashMap<String, u64> {
        FIXTURE
            .lines()
            .filter(|l| !l.starts_with('#') && !l.trim().is_empty())
            .map(|l| {
                let (k, v) = l.split_once(" = ").expect("fixture line is `key = value`");
                let v = match v.strip_prefix("0x") {
                    Some(hex) => u64::from_str_radix(hex, 16).unwrap(),
                    None => v.parse().unwrap(),
                };
                (k.to_string(), v)
            })
            .collect()
    }

    #[test]
    fn fixture_pins_upstream_commit_and_target() {
        assert!(FIXTURE.contains("ee3a4b233d3086f2db38dc9ec88a83c92678afc7"));
        assert!(FIXTURE.contains("x86_64 LP64"));
    }

    /// The only place layouts are compared to the C compiler's view of the real headers.
    /// Fixture offsets/sizes are for an LP64 target with the asm-generic ioctl encoding.
    #[test]
    #[cfg(all(
        target_pointer_width = "64",
        not(any(
            target_arch = "powerpc",
            target_arch = "powerpc64",
            target_arch = "mips",
            target_arch = "mips64",
            target_arch = "sparc",
            target_arch = "sparc64"
        ))
    ))]
    fn abi_matches_c_probe_fixture() {
        let f = fixture();
        let mut checked = 0usize;
        macro_rules! eq {
            ($key:expr, $val:expr) => {{
                let key: &str = $key;
                let want = *f
                    .get(key)
                    .unwrap_or_else(|| panic!("fixture lacks `{key}`"));
                assert_eq!($val as u64, want, "{key}");
                checked += 1;
            }};
        }

        eq!("sizeof(void*)", size_of::<*const u8>());

        eq!("sizeof(struct drm_event)", size_of::<DrmEvent>());
        eq!(
            "offsetof(struct drm_event, type)",
            offset_of!(DrmEvent, type_)
        );
        eq!(
            "offsetof(struct drm_event, length)",
            offset_of!(DrmEvent, length)
        );
        eq!("sizeof(struct drm_clip_rect)", size_of::<DrmClipRect>());
        eq!(
            "offsetof(struct drm_clip_rect, x1)",
            offset_of!(DrmClipRect, x1)
        );
        eq!(
            "offsetof(struct drm_clip_rect, y1)",
            offset_of!(DrmClipRect, y1)
        );
        eq!(
            "offsetof(struct drm_clip_rect, x2)",
            offset_of!(DrmClipRect, x2)
        );
        eq!(
            "offsetof(struct drm_clip_rect, y2)",
            offset_of!(DrmClipRect, y2)
        );

        eq!("sizeof(struct drm_version)", size_of::<DrmVersion>());
        eq!(
            "offsetof(struct drm_version, version_major)",
            offset_of!(DrmVersion, version_major)
        );
        eq!(
            "offsetof(struct drm_version, version_minor)",
            offset_of!(DrmVersion, version_minor)
        );
        eq!(
            "offsetof(struct drm_version, version_patchlevel)",
            offset_of!(DrmVersion, version_patchlevel)
        );
        eq!(
            "offsetof(struct drm_version, name_len)",
            offset_of!(DrmVersion, name_len)
        );
        eq!(
            "offsetof(struct drm_version, name)",
            offset_of!(DrmVersion, name)
        );
        eq!(
            "offsetof(struct drm_version, date_len)",
            offset_of!(DrmVersion, date_len)
        );
        eq!(
            "offsetof(struct drm_version, date)",
            offset_of!(DrmVersion, date)
        );
        eq!(
            "offsetof(struct drm_version, desc_len)",
            offset_of!(DrmVersion, desc_len)
        );
        eq!(
            "offsetof(struct drm_version, desc)",
            offset_of!(DrmVersion, desc)
        );
        eq!("DRM_IOCTL_VERSION", DRM_IOCTL_VERSION);
        eq!("DRM_IOCTL_DROP_MASTER", DRM_IOCTL_DROP_MASTER);
        eq!("DRM_COMMAND_BASE", DRM_COMMAND_BASE);

        eq!(
            "sizeof(struct drm_evdi_connect)",
            size_of::<DrmEvdiConnect>()
        );
        eq!(
            "offsetof(struct drm_evdi_connect, connected)",
            offset_of!(DrmEvdiConnect, connected)
        );
        eq!(
            "offsetof(struct drm_evdi_connect, dev_index)",
            offset_of!(DrmEvdiConnect, dev_index)
        );
        eq!(
            "offsetof(struct drm_evdi_connect, edid)",
            offset_of!(DrmEvdiConnect, edid)
        );
        eq!(
            "offsetof(struct drm_evdi_connect, edid_length)",
            offset_of!(DrmEvdiConnect, edid_length)
        );
        eq!(
            "offsetof(struct drm_evdi_connect, pixel_area_limit)",
            offset_of!(DrmEvdiConnect, pixel_area_limit)
        );
        eq!(
            "offsetof(struct drm_evdi_connect, pixel_per_second_limit)",
            offset_of!(DrmEvdiConnect, pixel_per_second_limit)
        );

        eq!(
            "sizeof(struct drm_evdi_request_update)",
            size_of::<DrmEvdiRequestUpdate>()
        );
        eq!(
            "offsetof(struct drm_evdi_request_update, reserved)",
            offset_of!(DrmEvdiRequestUpdate, reserved)
        );

        eq!(
            "sizeof(struct drm_evdi_grabpix)",
            size_of::<DrmEvdiGrabpix>()
        );
        eq!(
            "offsetof(struct drm_evdi_grabpix, mode)",
            offset_of!(DrmEvdiGrabpix, mode)
        );
        eq!(
            "offsetof(struct drm_evdi_grabpix, buf_width)",
            offset_of!(DrmEvdiGrabpix, buf_width)
        );
        eq!(
            "offsetof(struct drm_evdi_grabpix, buf_height)",
            offset_of!(DrmEvdiGrabpix, buf_height)
        );
        eq!(
            "offsetof(struct drm_evdi_grabpix, buf_byte_stride)",
            offset_of!(DrmEvdiGrabpix, buf_byte_stride)
        );
        eq!(
            "offsetof(struct drm_evdi_grabpix, buffer)",
            offset_of!(DrmEvdiGrabpix, buffer)
        );
        eq!(
            "offsetof(struct drm_evdi_grabpix, num_rects)",
            offset_of!(DrmEvdiGrabpix, num_rects)
        );
        eq!(
            "offsetof(struct drm_evdi_grabpix, rects)",
            offset_of!(DrmEvdiGrabpix, rects)
        );
        eq!("EVDI_GRABPIX_MODE_RECTS", GRABPIX_MODE_RECTS);
        eq!("EVDI_GRABPIX_MODE_DIRTY", GRABPIX_MODE_DIRTY);

        eq!(
            "sizeof(struct drm_evdi_event_update_ready)",
            EVENT_UPDATE_READY_SIZE
        );
        eq!("sizeof(struct drm_evdi_event_dpms)", EVENT_DPMS_SIZE);
        eq!("offsetof(struct drm_evdi_event_dpms, mode)", 8);
        eq!(
            "sizeof(struct drm_evdi_event_mode_changed)",
            EVENT_MODE_CHANGED_SIZE
        );
        // Decoder offsets in `parse_events` for the mode_changed event.
        eq!("offsetof(struct drm_evdi_event_mode_changed, hdisplay)", 8);
        eq!("offsetof(struct drm_evdi_event_mode_changed, vdisplay)", 12);
        eq!("offsetof(struct drm_evdi_event_mode_changed, vrefresh)", 16);
        eq!(
            "offsetof(struct drm_evdi_event_mode_changed, bits_per_pixel)",
            20
        );
        eq!(
            "offsetof(struct drm_evdi_event_mode_changed, pixel_format)",
            24
        );
        eq!(
            "sizeof(struct drm_evdi_event_crtc_state)",
            EVENT_CRTC_STATE_SIZE
        );
        eq!("offsetof(struct drm_evdi_event_crtc_state, state)", 8);

        eq!("DRM_EVDI_EVENT_UPDATE_READY", DRM_EVDI_EVENT_UPDATE_READY);
        eq!("DRM_EVDI_EVENT_DPMS", DRM_EVDI_EVENT_DPMS);
        eq!("DRM_EVDI_EVENT_MODE_CHANGED", DRM_EVDI_EVENT_MODE_CHANGED);
        eq!("DRM_EVDI_EVENT_CRTC_STATE", DRM_EVDI_EVENT_CRTC_STATE);
        eq!("DRM_EVDI_EVENT_CURSOR_SET", DRM_EVDI_EVENT_CURSOR_SET);
        eq!("DRM_EVDI_EVENT_CURSOR_MOVE", DRM_EVDI_EVENT_CURSOR_MOVE);
        eq!("DRM_EVDI_EVENT_DDCCI_DATA", DRM_EVDI_EVENT_DDCCI_DATA);

        eq!("DRM_EVDI_CONNECT", DRM_EVDI_CONNECT);
        eq!("DRM_EVDI_REQUEST_UPDATE", DRM_EVDI_REQUEST_UPDATE);
        eq!("DRM_EVDI_GRABPIX", DRM_EVDI_GRABPIX);
        eq!("DRM_IOCTL_EVDI_CONNECT", DRM_IOCTL_EVDI_CONNECT);
        eq!(
            "DRM_IOCTL_EVDI_REQUEST_UPDATE",
            DRM_IOCTL_EVDI_REQUEST_UPDATE
        );
        eq!("DRM_IOCTL_EVDI_GRABPIX", DRM_IOCTL_EVDI_GRABPIX);

        // Every fixture line except the ones for constants we deliberately do not use must
        // have been compared; a new probe line without a Rust counterpart should be a
        // conscious decision.
        assert_eq!(
            checked,
            f.len(),
            "fixture has lines this test does not compare"
        );
    }

    #[test]
    fn auth_magic_matches_the_kernel_header_value() {
        // include/uapi/drm/drm.h: DRM_IOW(0x11, struct drm_auth) with a 4-byte struct.
        assert_eq!(DRM_IOCTL_AUTH_MAGIC, 0x4004_6411);
    }

    #[test]
    fn connect_request_is_command_zero_iowr_of_32_bytes() {
        // The reviewer's formula, independent of the fixture.
        let expected = (3u32 << 30) | (32 << 16) | ((b'd' as u32) << 8) | 0x40;
        assert_eq!(DRM_IOCTL_EVDI_CONNECT, expected);
        assert_eq!(ioc_dir(DRM_IOCTL_EVDI_CONNECT), IOC_READ | IOC_WRITE);
        assert_eq!(ioc_size(DRM_IOCTL_EVDI_CONNECT), 32);
        assert_eq!(ioc_nr(DRM_IOCTL_EVDI_CONNECT), 0x40);
        assert_eq!(ioc_type(DRM_IOCTL_EVDI_CONNECT), b'd');
        assert_ne!(DRM_IOCTL_EVDI_CONNECT, DRM_IOCTL_EVDI_GRABPIX);
    }

    fn event(ty: u32, payload: &[i32]) -> Vec<u8> {
        let mut v = Vec::new();
        v.extend_from_slice(&ty.to_ne_bytes());
        v.extend_from_slice(&((8 + payload.len() * 4) as u32).to_ne_bytes());
        for p in payload {
            v.extend_from_slice(&p.to_ne_bytes());
        }
        v
    }

    #[test]
    fn parse_events_decodes_packed_stream() {
        let mut buf = event(
            DRM_EVDI_EVENT_MODE_CHANGED,
            &[1920, 1080, 60, 32, 0x3432_5258],
        );
        buf.extend(event(DRM_EVDI_EVENT_UPDATE_READY, &[]));
        buf.extend(event(DRM_EVDI_EVENT_DPMS, &[0]));
        buf.extend(event(DRM_EVDI_EVENT_CURSOR_MOVE, &[3, 4]));
        assert_eq!(
            parse_events(&buf),
            vec![
                EvdiEvent::ModeChanged {
                    hdisplay: 1920,
                    vdisplay: 1080,
                    vrefresh: 60,
                    bits_per_pixel: 32,
                    pixel_format: 0x3432_5258,
                },
                EvdiEvent::UpdateReady,
                EvdiEvent::Dpms(0),
                EvdiEvent::Other(DRM_EVDI_EVENT_CURSOR_MOVE),
            ]
        );
    }

    #[test]
    fn parse_events_survives_garbage() {
        assert!(parse_events(&[]).is_empty());
        assert!(parse_events(&[1, 2, 3]).is_empty());
        // a bare update_ready header is a complete event
        assert_eq!(
            parse_events(&event(DRM_EVDI_EVENT_UPDATE_READY, &[])),
            vec![EvdiEvent::UpdateReady]
        );
        // length smaller than the header
        let mut bad = DRM_EVDI_EVENT_UPDATE_READY.to_ne_bytes().to_vec();
        bad.extend_from_slice(&4u32.to_ne_bytes());
        assert!(parse_events(&bad).is_empty());
        // length runs past the buffer
        let mut long = DRM_EVDI_EVENT_UPDATE_READY.to_ne_bytes().to_vec();
        long.extend_from_slice(&64u32.to_ne_bytes());
        assert!(parse_events(&long).is_empty());
        // mode_changed shorter than its struct is reported as Other, not decoded
        assert_eq!(
            parse_events(&event(DRM_EVDI_EVENT_MODE_CHANGED, &[1, 2])),
            vec![EvdiEvent::Other(DRM_EVDI_EVENT_MODE_CHANGED)]
        );
    }
}
